boolean isPalindrome(String s) {
    StringBuilder clean = new StringBuilder();
    for (char ch : s.toCharArray()) {
        if (Character.isLetterOrDigit(ch)) clean.append(Character.toLowerCase(ch));   // keep letters and digits
    }
    String forwards = clean.toString();
    return forwards.equals(clean.reverse().toString());   // equal to its own reverse?
}

bool isPalindrome(string s) {
    string clean;
    for (char ch : s) {
        if (isalnum((unsigned char)ch)) clean += (char)tolower((unsigned char)ch);   // keep letters and digits
    }
    return clean == string(clean.rbegin(), clean.rend());   // equal to its own reverse?
}

function isPalindrome(s) {
  const ok = (ch) => /[a-z0-9]/i.test(ch);   // letters and digits count; the rest is skipped
  let left = 0, right = s.length - 1;
  while (left < right) {
    if (!ok(s[left])) { left++; continue; }   // skip spaces and punctuation
    if (!ok(s[right])) { right--; continue; }
    if (s[left].toLowerCase() !== s[right].toLowerCase()) return false;   // a mismatch
    left++;
    right--;
  }
  return true;
}

def is_palindrome(s):
    left, right = 0, len(s) - 1
    while left < right:
        if not s[left].isalnum():
            left += 1                     # skip spaces and punctuation
        elif not s[right].isalnum():
            right -= 1
        elif s[left].lower() != s[right].lower():
            return False                  # a mismatch
        else:
            left += 1
            right -= 1
    return True

boolean isPalindrome(String s) {
    int left = 0, right = s.length() - 1;
    while (left < right) {
        char a = s.charAt(left), b = s.charAt(right);
        if (!Character.isLetterOrDigit(a)) left++;               // skip spaces and punctuation
        else if (!Character.isLetterOrDigit(b)) right--;
        else if (Character.toLowerCase(a) != Character.toLowerCase(b)) return false;   // a mismatch
        else {
            left++;
            right--;
        }
    }
    return true;
}

bool isPalindrome(string s) {
    int left = 0, right = (int)s.size() - 1;
    while (left < right) {
        unsigned char a = s[left], b = s[right];
        if (!isalnum(a)) left++;                     // skip spaces and punctuation
        else if (!isalnum(b)) right--;
        else if (tolower(a) != tolower(b)) return false;   // a mismatch
        else {
            left++;
            right--;
        }
    }
    return true;
}
